#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""TEMPLATE: build_sections.py — generated by new_book.py.
注入项: SECTIONS / NOTES_SUBHEADS"""
import json, os, re

HERE = os.path.dirname(os.path.abspath(__file__))
items = json.load(open(os.path.join(HERE, 'stream_raw.json'), encoding='utf-8'))

SECTIONS = [
    ('intro', '緒章', (6, 15), False),
    ('ch1', '第一章 · 清末輪船招商局與美商旗昌洋行的交易', (16, 34), False),
    ('ch2', '第二章 · 清末民初中美版權之爭', (35, 56), False),
    ('ch3', '第三章 · 民初江南造船所成功打造美國萬噸巨輪', (57, 74), False),
    ('ch4', '第四章 · 一種特殊機遇與多元關係網', (75, 94), False),
    ('ch5', '第五章 · 在華商人團體的成立與轉型', (95, 124), False),
    ('ch6', '第六章 · 在華技術組織的成立與演變', (125, 152), False),
    ('ch7', '第七章 · 中國抗戰初期美國在華跨國企業的遭逢', (153, 171), False),
    ('ch8', '第八章 · 戰爭與石油', (172, 192), False),
    ('ch9', '第九章 · 戰後中美新經濟關係的建立', (193, 212), False),
    ('concl', '結論', (213, 219), False),
    ('appendix', '附錄', (220, 227), False),
    ('biblio', '徵引書目', (228, 248), False),
    ('afterword', '後記', (249, 253), False),
]
NOTES_SUBHEADS = set()

def norm(s):
    return ' '.join(s.split())

def is_noise(t):
    t = t.strip()
    if not t:
        return True
    if re.fullmatch(r'[\d\s\.\-\[\]ivxlcdmIVXLCDM]+', t):
        return True
    return False

def first_on_page(pg):
    for x in items:
        if x['page'] == pg and x['type'] in ('text', 'ref_text'):
            t = norm(x['text']).strip()
            if not is_noise(t) and t != 'This page intentionally left blank':
                return t
    return None

def load_appendix():
    p = os.path.join(HERE, 'appendix_items.json')
    if os.path.isfile(p):
        return json.load(open(p, encoding='utf-8'))
    return []


def main():
    results = []
    apdx = load_appendix()
    for sid, title, (a, b), is_notes in SECTIONS:
        paras = []
        if is_notes:
            pending = None
            def flush():
                nonlocal pending
                if pending:
                    paras.append({"type": 'note', "text": pending})
                pending = None
            for x in items:
                if x['page'] < a or x['page'] > b:
                    continue
                t = norm(x['text']).strip()
                if is_noise(t) or t == 'This page intentionally left blank':
                    continue
                if t in NOTES_SUBHEADS:
                    flush(); paras.append({"type": 'subh', "text": t}); continue
                if re.match(r'^\d+\.\s', t) or re.match(r'^[a-z]\.\s', t):
                    flush(); pending = t
                else:
                    pending = t if pending is None else pending + ' ' + t
            flush()
        else:
            for x in items:
                if x['page'] < a or x['page'] > b:
                    continue
                t = norm(x['text']).strip()
                if is_noise(t) or t == 'This page intentionally left blank':
                    continue
                lvl = x.get('lvl')
                if re.match(r'^第[一二三四五六七八九十百]+章', t):
                    paras.append({"type": 'h1', "text": t}); continue
                if re.match(r'^(緒章|緒論|導論|結論|後記|附錄|徵引書目|參考文獻)', t) and len(t) <= 12:
                    paras.append({"type": 'h1', "text": t}); continue
                if re.match(r'^(前言|小結|結論|結語|導言|引言|餘論|後論)$', t):
                    paras.append({"type": 'h2', "text": t}); continue
                if lvl == 1:
                    paras.append({"type": 'h1', "text": t}); continue
                if lvl == 2:
                    paras.append({"type": 'h2', "text": t}); continue
                if len(t) <= 24 and re.match(r'^(?:[一二三四五六七八九十]+、|\([一二三四五六七八九十]+\)|\d+[\.、]\s*\S)', t):
                    paras.append({"type": 'h2', "text": t}); continue
                paras.append({"type": 'text', "text": t})
            # 页底脚注（MinerU page_footnote）：附加在本节正文之后，供悬浮提示使用
            for x in items:
                if x['page'] < a or x['page'] > b:
                    continue
                if x['type'] != 'page_footnote':
                    continue
                t = norm(x['text']).strip()
                if is_noise(t):
                    continue
                paras.append({"type": 'note', "text": t})
            # 附录：嵌入表格图片
            if sid == 'appendix':
                for it in apdx:
                    if it.get('caption'):
                        paras.append({"type": 'cap', "text": it['caption']})
                    if it.get('img'):
                        paras.append({"type": 'table', "text": it['img']})
        dedup = []
        for p in paras:
            if dedup and dedup[-1]['text'] == p['text'] and dedup[-1]['type'] == p['type']:
                continue
            dedup.append(p)
        seen = set(); uniq = []
        for p in dedup:
            k = (p['type'], p['text'][:80])
            if k in seen:
                continue
            seen.add(k); uniq.append(p)
        dedup = uniq
        # 章标题（第X章）后紧跟的短标题 → 作为章副题 h1sub
        for i, p in enumerate(dedup):
            if p['type'] == 'h1' and re.match(r'^第[一二三四五六七八九十百]+章', p['text']):
                if i + 1 < len(dedup):
                    q = dedup[i + 1]
                    if q['type'] in ('h1', 'h2') and len(q['text']) <= 42 and not re.search(r'[。；!？]', q['text']):
                        q['type'] = 'h1sub'
        results.append({"id": sid, "title": title, "paras": dedup})
        print(f"{sid:12s} paras={len(dedup):4d} chars={sum(len(p['text']) for p in dedup):7d} | {(dedup[0]['text'][:40] if dedup else '')}", flush=True)
    with open(os.path.join(HERE, 'en_data.json'), 'w', encoding='utf-8') as f:
        json.dump(results, f, ensure_ascii=False)
    print(f"\nTOTAL sections={len(results)} paras={sum(len(s['paras']) for s in results)}", flush=True)

if __name__ == '__main__':
    main()